// ─É─ö POST /api/auth/check-email ─É─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö─ö
// Kiểm tra email đã tồn tại chưa (dùng trước khi đăng ký để báo lỗi sớm)
app.post("/api/auth/check-email", async (req, res) => {
  const { email } = req.body || {};
  if (!email) return res.status(400).json({ message: "Email là bắt buộc." });

  try {
    const result = await pool.query(
      "SELECT id, google_id FROM users WHERE email = $1",
      [email.toLowerCase().trim()]
    );
    if (result.rows.length === 0) {
      return res.json({ available: true });
    }
    if (result.rows[0].google_id) {
      return res.status(409).json({
        available: false,
        isGoogleAccount: true,
        message: "Email này đã được đăng ký qua Google. Vui lòng đăng nhập bằng Google.",
      });
    }
    return res.status(409).json({
      available: false,
      isGoogleAccount: false,
      message: "Email này đã được đăng ký. Vui lòng đăng nhập.",
    });
  } catch (err) {
    console.error("check-email error:", err);
    return res.status(500).json({ message: "Lỗi máy chủ." });
  }
});

// ΓöÇΓöÇΓöÇ POST /api/auth/register ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// ─É─âng k├╜ bß║▒ng email + password
app.post("/api/auth/register", async (req, res) => {
  try {
    const { fullName, email, password, role, phone, city, avatarUrl } = req.body || {};

    // Validate
    if (!fullName || !email || !password) {
      return res
        .status(400)
        .json({ message: "Họ tên, email và mật khẩu là bắt buộc." });
    }
    if (password.length < 8) {
      return res
        .status(400)
        .json({ message: "Mật khẩu phải có ít nhất 8 ký tự." });
    }

    const allowedRoles = ["student", "parent", "tutor"];
    const userRole = allowedRoles.includes(role) ? role : "student";

    // Kiß╗âm tra email ─æ├ú tß╗ôn tß║íi ch╞░a
    const existing = await pool.query(
      "SELECT id, google_id FROM users WHERE email = $1",
      [email.toLowerCase().trim()]
    );
    if (existing.rows.length > 0) {
      if (existing.rows[0].google_id) {
        return res.status(409).json({
          message: "Email này đã được đăng ký qua Google. Vui lòng đăng nhập bằng Google.",
          isGoogleAccount: true,
        });
      }
      return res
        .status(409)
        .json({ message: "Email đã được đăng ký. Vui lòng đăng nhập." });
    }

    // Hash password
    const passwordHash = await bcrypt.hash(password, 12);

    // Tạo OTP 6 số
    const otp = Math.floor(100000 + Math.random() * 900000).toString();
    const expiry = new Date(Date.now() + 10 * 60 * 1000); // 10 minutes

    // Lưu thông tin vào registration_otps (Upsert)
    const userData = {
      fullName: fullName.trim(),
      email: email.toLowerCase().trim(),
      passwordHash,
      userRole,
      phone: phone || null,
      city: city || null,
      avatarUrl: avatarUrl || null
    };

    await pool.query(
      `INSERT INTO registration_otps (email, otp, expiry, user_data)
       VALUES ($1, $2, $3, $4)
       ON CONFLICT (email) DO UPDATE SET otp = EXCLUDED.otp, expiry = EXCLUDED.expiry, user_data = EXCLUDED.user_data`,
      [email.toLowerCase().trim(), otp, expiry, JSON.stringify(userData)]
    );

    // Gửi email
    sendRegistrationOtpEmail(email.toLowerCase().trim(), otp).catch(console.error);

    return res.status(202).json({
      requireOtp: true,
      message: "Vui lòng kiểm tra email để lấy mã OTP."
    });
  } catch (error) {
    console.error("Register error:", error);
    return res.status(500).json({ message: "Lỗi máy chủ. Vui lòng thử lại." });
  }
});

// POST /api/auth/verify-register-otp
app.post("/api/auth/verify-register-otp", async (req, res) => {
  try {
    const { email, otp } = req.body || {};
    if (!email || !otp) {
      return res.status(400).json({ message: "Thiếu thông tin." });
    }

    const result = await pool.query("SELECT * FROM registration_otps WHERE email = $1", [email.toLowerCase().trim()]);
    if (result.rows.length === 0) {
      return res.status(400).json({ message: "Mã OTP không hợp lệ hoặc đã hết hạn." });
    }

    const record = result.rows[0];
    if (record.otp !== otp) {
      return res.status(400).json({ message: "Mã OTP không chính xác." });
    }

    if (new Date() > new Date(record.expiry)) {
      return res.status(400).json({ message: "Mã OTP đã hết hạn." });
    }

    const userData = record.user_data;

    // Tiến hành tạo user
    const insertResult = await pool.query(
      `INSERT INTO users (full_name, email, password_hash, role, phone, city, picture)
       VALUES ($1, $2, $3, $4, $5, $6, $7)
       RETURNING id, full_name, email, role, picture, created_at`,
      [userData.fullName, userData.email, userData.passwordHash, userData.userRole, userData.phone, userData.city, userData.avatarUrl]
    );

    const newUser = insertResult.rows[0];
    const token = createToken(newUser);

    // Xóa record OTP
    await pool.query("DELETE FROM registration_otps WHERE email = $1", [userData.email]);

    // Email chào mừng (qua outbox — không chặn response đăng ký)
    await safeNotifyUser(pool, {
      userId: newUser.id, type: 'welcome',
      channels: ['IN_APP', 'EMAIL'],
      templateKey: 'welcome_user', eventType: 'welcome_user',
      idempotencyKey: `welcome:${newUser.id}`,
      data: { name: newUser.full_name },
    });

    return res.status(201).json({
      token,
      user: {
        id: newUser.id,
        name: newUser.full_name,
        email: newUser.email,
        role: newUser.role,
        picture: newUser.picture,
      },
    });
  } catch (error) {
    console.error("Verify OTP error:", error);
    return res.status(500).json({ message: "Lỗi máy chủ." });
  }
});

// ─── GET /api/email/unsubscribe?token= ── hủy đăng ký email từ footer ────────
app.get("/api/email/unsubscribe", async (req, res) => {
  const page = (msg, ok) => `<!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8"/><title>EduX</title></head>
<body style="margin:0;font-family:'Segoe UI',Arial,sans-serif;background:#f8f9fb;display:flex;align-items:center;justify-content:center;min-height:100vh;">
<div style="background:#fff;border-radius:16px;padding:40px;max-width:420px;text-align:center;box-shadow:0 4px 24px rgba(0,0,0,0.08);">
<h1 style="margin:0 0 8px;color:#00288e;font-size:22px;">EduX</h1>
<p style="margin:0;color:${ok ? '#15803d' : '#b91c1c'};font-size:15px;line-height:1.6;">${msg}</p>
</div></body></html>`;
  try {
    const decoded = jwt.verify(String(req.query.token || ''), jwtSecret);
    if (decoded.purpose !== 'email_unsub' || !decoded.userId) throw new Error('bad purpose');
    await pool.query('UPDATE users SET email_opt_out = TRUE WHERE id = $1', [decoded.userId]);
    return res.send(page('Đã hủy đăng ký email thông báo. Bạn vẫn nhận được thông báo trên web và các email bảo mật (OTP).', true));
  } catch {
    return res.status(400).send(page('Liên kết hủy đăng ký không hợp lệ hoặc đã hết hạn.', false));
  }
});

// ΓöÇΓöÇΓöÇ POST /api/auth/forgot-password/request-otp ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
app.post("/api/auth/forgot-password/request-otp", async (req, res) => {
  try {
    const { email } = req.body || {};
    if (!email) {
      return res.status(400).json({ message: "Email là bắt buộc." });
    }

    const result = await pool.query("SELECT id, email FROM users WHERE email = $1", [email.toLowerCase().trim()]);
    if (result.rows.length === 0) {
      // Don't reveal if email exists or not, just return success
      return res.json({ message: "Nếu email tồn tại, OTP đã được gửi." });
    }

    // Generate 6-digit OTP
    const otp = Math.floor(100000 + Math.random() * 900000).toString();
    const expiry = new Date(Date.now() + 10 * 60 * 1000); // 10 minutes

    await pool.query(
      "UPDATE users SET reset_otp = $1, reset_otp_expiry = $2 WHERE email = $3",
      [otp, expiry, result.rows[0].email]
    );

    // Send email without blocking
    sendPasswordResetEmail(result.rows[0].email, otp).catch(console.error);

    return res.json({ message: "OTP đã được gửi đến email của bạn." });
  } catch (error) {
    console.error("Request OTP error:", error);
    return res.status(500).json({ message: "Lỗi máy chủ." });
  }
});

// ΓöÇΓöÇΓöÇ POST /api/auth/forgot-password/reset ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
app.post("/api/auth/forgot-password/reset", async (req, res) => {
  try {
    const { email, otp, newPassword } = req.body || {};
    if (!email || !otp || !newPassword) {
      return res.status(400).json({ message: "Thiếu thông tin yêu cầu." });
    }

    if (newPassword.length < 8) {
      return res.status(400).json({ message: "Mật khẩu phải dài ít nhất 8 ký tự." });
    }

    const result = await pool.query(
      "SELECT id, reset_otp, reset_otp_expiry FROM users WHERE email = $1",
      [email.toLowerCase().trim()]
    );

    if (result.rows.length === 0) {
      return res.status(400).json({ message: "OTP không hợp lệ hoặc đã hết hạn." });
    }

    const user = result.rows[0];

    if (!user.reset_otp || user.reset_otp !== otp.trim()) {
      return res.status(400).json({ message: "Mã OTP không chính xác." });
    }

    if (new Date() > new Date(user.reset_otp_expiry)) {
      return res.status(400).json({ message: "Mã OTP đã hết hạn. Vui lòng yêu cầu lại." });
    }

    // OTP hß╗úp lß╗ç, tiß║┐n h├ánh ─æß╗òi mß║¡t khß║⌐u
    const saltRounds = 12;
    const passwordHash = await bcrypt.hash(newPassword, saltRounds);

    await pool.query(
      "UPDATE users SET password_hash = $1, reset_otp = NULL, reset_otp_expiry = NULL WHERE id = $2",
      [passwordHash, user.id]
    );

    return res.json({ message: "Đặt lại mật khẩu thành công!" });
  } catch (error) {
    console.error("Reset password error:", error);
    return res.status(500).json({ message: "Lỗi máy chủ." });
  }
});

// ΓöÇΓöÇΓöÇ POST /api/auth/login ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// ─É─âng nhß║¡p bß║▒ng email + password
app.post("/api/auth/login", async (req, res) => {
  try {
    const { email, password } = req.body || {};

    if (!email || !password) {
      return res
        .status(400)
        .json({ message: "Email và mật khẩu là bắt buộc." });
    }

    // T├¼m user theo email
    const result = await pool.query(
      `SELECT u.id, u.full_name, u.email, u.password_hash, u.role, u.picture,
              tp.status AS tutor_status
       FROM users u
       LEFT JOIN tutor_profiles tp ON tp.user_id = u.id
       WHERE u.email = $1`,
      [email.toLowerCase().trim()]
    );

    if (result.rows.length === 0) {
      return res
        .status(401)
        .json({ message: "Email hoặc mật khẩu không hợp lệ." });
    }

    const user = result.rows[0];

    // User ─æ─âng k├╜ bß║▒ng Google, kh├┤ng c├│ password
    if (!user.password_hash) {
      return res.status(401).json({
        message: "Tài khoản này sử dụng đăng nhập Google. Vui lòng sử dụng Google để đăng nhập.",
      });
    }

    // Kiß╗âm tra password
    const isMatch = await bcrypt.compare(password, user.password_hash);
    if (!isMatch) {
      return res.status(401).json({ message: "Email hoặc mật khẩu không hợp lệ." });
    }

    const token = createToken(user);

    const ip = getClientIP(req);
    const suspicious = await logLoginAttempt(user.id, ip, req.headers['user-agent']);

    return res.json({
      token,
      user: {
        id: user.id,
        name: user.full_name,
        email: user.email,
        role: user.role,
        picture: user.picture,
        tutor_status: user.role === 'tutor' ? (user.tutor_status || null) : undefined,
      },
      suspiciousLogin: suspicious,
      loginIP: ip,
    });

  } catch (error) {
    console.error("Login error:", error);
    return res.status(500).json({ message: "Lỗi máy chủ. Vui lòng thử lại." });
  }
});

// ΓöÇΓöÇΓöÇ POST /api/auth/google ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// ─É─âng nhß║¡p / ─æ─âng k├╜ bß║▒ng Google OAuth ΓÇö l╞░u v├áo DB
app.post("/api/auth/google", async (req, res) => {
  try {
    const { credential } = req.body || {};

    if (!googleClientId) {
      return res
        .status(500)
        .json({ message: "GOOGLE_CLIENT_ID chưa được cấu hình trên máy chủ." });
    }
    if (!credential) {
      return res.status(400).json({ message: "Thiếu thông tin xác thực Google." });
    }

    // Verify Google token
    const ticket = await googleClient.verifyIdToken({
      idToken: credential,
      audience: googleClientId,
    });

    const payload = ticket.getPayload();
    if (!payload?.email || !payload?.sub) {
      return res.status(401).json({ message: "Dữ liệu token Google không hợp lệ." });
    }

    const googleId = payload.sub;
    const email = payload.email.toLowerCase().trim();
    const name = payload.name || "";
    const picture = payload.picture || "";

    // T├¼m user ─æ├ú c├│ ch╞░a (theo google_id hoß║╖c email)
    let userResult = await pool.query(
      "SELECT id, full_name, email, role, picture FROM users WHERE google_id = $1 OR email = $2",
      [googleId, email]
    );

    let user;
    if (userResult.rows.length > 0) {
      // ─É├ú c├│ ΓåÆ cß║¡p nhß║¡t google_id v├á picture nß║┐u cß║ºn
      user = userResult.rows[0];
      await pool.query(
        "UPDATE users SET google_id = $1, picture = $2 WHERE id = $3",
        [googleId, picture, user.id]
      );
      user.picture = picture;
    } else {
      // Ch╞░a c├│ ΓåÆ tß║ío mß╗¢i vß╗¢i role mß║╖c ─æß╗ïnh 'student'
      const insertResult = await pool.query(
        `INSERT INTO users (full_name, email, google_id, picture, role)
         VALUES ($1, $2, $3, $4, 'student')
         RETURNING id, full_name, email, role, picture`,
        [name, email, googleId, picture]
      );
      user = insertResult.rows[0];
    }

    const token = createToken(user);

    const ip = getClientIP(req);
    const suspicious = await logLoginAttempt(user.id, ip, req.headers['user-agent']);

    return res.json({
      token,
      user: {
        id: user.id,
        name: user.full_name,
        email: user.email,
        role: user.role,
        picture: user.picture,
      },
      suspiciousLogin: suspicious,
      loginIP: ip,
    });
  } catch (error) {
    console.error("Google auth error:", error);
    return res.status(401).json({ message: "Xác thực Google thất bại." });
  }
});

