// 3. VNPAY IPN Webhook
app.get('/api/payment/vnpay-ipn', async (req, res) => {
  try {
      let vnp_Params = { ...req.query };
      const secureHash = vnp_Params['vnp_SecureHash'];
      const amount = vnp_Params['vnp_Amount'] / 100;
      const orderId = vnp_Params['vnp_TxnRef'];
      const responseCode = vnp_Params['vnp_ResponseCode'];
      const walletId = vnp_Params['vnp_OrderInfo']; 

      delete vnp_Params['vnp_SecureHash'];
      delete vnp_Params['vnp_SecureHashType'];

      // Sắp xếp key theo alphabet rồi tự build query string
      const sortedKeys = Object.keys(vnp_Params).sort();
      const signParts = [];
      for (const key of sortedKeys) {
          const encKey = encodeURIComponent(key);
          const encVal = encodeURIComponent(String(vnp_Params[key])).replace(/%20/g, '+');
          signParts.push(encKey + '=' + encVal);
      }
      const signData = signParts.join('&');

      const secretKey = process.env.VNPAY_SECRET_KEY || 'DEMOSECRETKEY1234567890';
      const hmac = crypto.createHmac('sha512', secretKey);
      const signed = hmac.update(Buffer.from(signData, 'utf-8')).digest('hex');

      console.log('[VNPAY IPN] signData:', signData);
      console.log('[VNPAY IPN] signed:', signed, '| secureHash:', secureHash);

      if (secureHash !== signed) {
          return res.status(200).json({ RspCode: '97', Message: 'Checksum failed' });
      }

      if (responseCode !== '00') {
           return res.status(200).json({ RspCode: '00', Message: 'Success processing failed transaction' });
      }

      // Call RPC process_deposit inside a transaction so the wallet ledger
      // trigger records a DEPOSIT_VNPAY reason (Batch 17)
      let isSuccess;
      const depClient = await pool.connect();
      try {
        await depClient.query('BEGIN');
        await setLedgerContext(depClient, { reason_code: 'DEPOSIT_VNPAY', source: 'webhook', reference_type: 'transaction', metadata: { orderId } });
        const dbRes = await depClient.query('SELECT process_deposit($1, $2, $3, $4) AS success', [walletId, amount, 'VNPAY', orderId]);
        isSuccess = dbRes.rows[0].success;
        await depClient.query('COMMIT');
      } catch (depErr) {
        await depClient.query('ROLLBACK').catch(() => {});
        throw depErr;
      } finally {
        depClient.release();
      }

      if (!isSuccess) {
           return res.status(200).json({ RspCode: '02', Message: 'Order already confirmed' });
      }

      // Email biên nhận nạp tiền (idempotent theo orderId — IPN có thể gọi lại)
      try {
        const owner = await pool.query('SELECT user_id FROM wallets WHERE id = $1', [walletId]);
        if (owner.rows[0]?.user_id) {
          await safeNotifyUser(pool, {
            userId: owner.rows[0].user_id, type: 'wallet_topup',
            channels: ['IN_APP', 'EMAIL'],
            templateKey: 'wallet_topup_success', eventType: 'wallet_topup_success',
            refId: null, refType: 'wallet',
            idempotencyKey: `wallet_topup:${orderId}`,
            data: { amount, provider: 'VNPAY', txnRef: orderId },
          });
        }
      } catch (notifyErr) {
        console.error('[vnpay-ipn] notify error (non-fatal):', notifyErr.message);
      }

      res.status(200).json({ RspCode: '00', Message: 'Confirm Success' });
  } catch (err) {
      console.error('IPN Error:', err);
      res.status(200).json({ RspCode: '99', Message: 'Unknown error' });
  }
});


// ══════════════════════════════════════════════════════════════════════════════
//  ESCROW EXTENDED — Report, Manual Release, Wallet History
// ══════════════════════════════════════════════════════════════════════════════

// POST /api/bookings/:id/report — Học sinh / Phụ huynh báo cáo vi phạm gia sư
app.post('/api/bookings/:id/report', verifyToken, async (req, res) => {
  const client = await pool.connect();
  try {
    const { reason, severity = 'medium', evidenceUrls, requestedResolution } = req.body;
    if (!reason?.trim()) return res.status(400).json({ message: 'Vui lòng cung cấp lý do báo cáo.' });
    if (!Array.isArray(evidenceUrls) || evidenceUrls.length === 0) return res.status(400).json({ message: 'Vui lòng đính kèm bằng chứng hình ảnh trước khi gửi báo cáo.' });

    let bookingQuery;
    let queryParams;
    let isParent = false;

    if (req.user.role === 'parent') {
      bookingQuery = `
        SELECT b.* FROM bookings b
        JOIN parent_children pc ON b.student_id = pc.student_id
        WHERE b.id = $1 AND pc.parent_id = $2
      `;
      queryParams = [req.params.id, req.user.userId];
      isParent = true;
    } else {
      bookingQuery = `SELECT b.* FROM bookings b WHERE b.id = $1 AND b.student_id = $2`;
      queryParams = [req.params.id, req.user.userId];
    }

    const bookingRes = await client.query(bookingQuery, queryParams);
    if (!bookingRes.rows.length) return res.status(404).json({ message: 'Không tìm thấy lịch học hoặc bạn không có quyền truy cập.' });
    const booking = bookingRes.rows[0];

    const sessionStart = lessonStartFrom(booking.lesson_date, booking.time_slot);
    const sessionEnd = lessonEndFrom(booking.lesson_date, booking.time_slot);
    const now = new Date();
    if (sessionStart && now < sessionStart) {
      return res.status(400).json({ message: 'Buổi học chưa diễn ra.' });
    }
    if (sessionEnd && (now - sessionEnd) > 48 * 3600000) {
      return res.status(400).json({ message: 'Đã quá thời hạn báo cáo buổi học này (48 giờ sau khi kết thúc).' });
    }

    if (!booking.escrow_tx_id) return res.status(400).json({ message: 'Lịch học này không có giao dịch escrow để khiếu nại.' });

    const existingDispute = await client.query(
      "SELECT id FROM disputes WHERE booking_id=$1 AND status='OPEN' AND withdrawn_at IS NULL", [booking.id]
    );
    if (existingDispute.rows.length) return res.status(409).json({ message: 'Bạn đã gửi khiếu nại cho buổi học này rồi.' });

    await client.query('BEGIN');

    const dispute = await client.query(`
      INSERT INTO disputes (transaction_id, raised_by, reason, status, booking_id, target_type, tutor_id, severity, raised_by_parent, evidence_urls, student_requested_resolution)
      VALUES ($1, $2, $3, 'OPEN', $4, 'booking', $5, $6, $7, $8, $9) RETURNING id
    `, [booking.escrow_tx_id, req.user.userId, reason.trim(), booking.id, booking.tutor_id, severity, isParent, evidenceUrls, requestedResolution?.trim() || null]);

    // Pause auto-release
    await client.query(`UPDATE bookings SET auto_release_at=NULL WHERE id=$1`, [booking.id]);

    const admins = await client.query("SELECT id FROM users WHERE role='admin'");
    const reporterName = isParent ? 'Phụ huynh' : 'Học sinh';
    for (const admin of admins.rows) {
      await safeNotifyUser(client, {
        userId: admin.id, channels: ['IN_APP', 'EMAIL'],
        templateKey: 'dispute_opened', eventType: 'dispute_opened',
        data: { forAdmin: true, reporterName, reason: `báo cáo vi phạm buổi học ID: ${booking.id}. Lý do: ${reason}` },
        refId: dispute.rows[0].id, refType: 'dispute',
        sourceType: 'dispute', sourceId: dispute.rows[0].id,
        idempotencyKey: `dispute:${dispute.rows[0].id}:opened:${admin.id}`,
      });
    }
    if (booking.tutor_id) {
      await safeNotifyUser(client, {
        userId: booking.tutor_id, channels: ['IN_APP', 'EMAIL'],
        templateKey: 'dispute_opened', eventType: 'dispute_opened',
        data: { forAdmin: false, reporterName },
        refId: dispute.rows[0].id, refType: 'dispute',
        sourceType: 'dispute', sourceId: dispute.rows[0].id,
        idempotencyKey: `dispute:${dispute.rows[0].id}:opened:${booking.tutor_id}`,
      });
    }

    await client.query('COMMIT');
    return res.status(201).json({ message: 'Đã gửi báo cáo. Admin sẽ xem xét trong 24-48h.', disputeId: dispute.rows[0].id });
  } catch (e) {
    await client.query('ROLLBACK');
    console.error('Report error:', e);
    return res.status(500).json({ message: 'Lỗi máy chủ.' });
  } finally {
    client.release();
  }
});

// PATCH /api/bookings/disputes/:disputeId/tutor-response — gia sư giải trình cho 1 dispute liên quan tới mình
app.patch('/api/bookings/disputes/:disputeId/tutor-response', verifyToken, async (req, res) => {
  const client = await pool.connect();
  try {
    const { response } = req.body;
    if (!response?.trim()) return res.status(400).json({ message: 'Vui lòng nhập nội dung giải trình.' });

    const dRes = await client.query('SELECT * FROM disputes WHERE id=$1', [req.params.disputeId]);
    if (!dRes.rows.length) return res.status(404).json({ message: 'Không tìm thấy khiếu nại.' });
    const dispute = dRes.rows[0];

    if (dispute.tutor_id !== req.user.userId) {
      return res.status(403).json({ message: 'Bạn không có quyền phản hồi khiếu nại này.' });
    }
    if (dispute.withdrawn_at) {
      return res.status(409).json({ message: 'Khiếu nại này đã được học sinh rút, không thể xử lý/phản hồi.' });
    }
    if (dispute.status !== 'OPEN') {
      return res.status(409).json({ message: 'Khiếu nại đã được xử lý, không thể phản hồi.' });
    }

    await client.query('BEGIN');
    const updated = await client.query(
      `UPDATE disputes SET tutor_response=$1, tutor_response_at=NOW() WHERE id=$2 RETURNING *`,
      [response.trim(), req.params.disputeId]
    );

    const admins = await client.query("SELECT id FROM users WHERE role='admin'");
    for (const admin of admins.rows) {
      await safeNotifyUser(client, {
        userId: admin.id, channels: ['IN_APP'],
        templateKey: 'dispute_tutor_responded', eventType: 'dispute_tutor_responded',
        data: { forAdmin: true, disputeId: req.params.disputeId },
        refId: req.params.disputeId, refType: 'dispute',
        sourceType: 'dispute', sourceId: req.params.disputeId,
        idempotencyKey: `dispute:${req.params.disputeId}:tutor_responded:${admin.id}`,
      });
    }

    await client.query('COMMIT');
    return res.json({ success: true, dispute: updated.rows[0] });
  } catch (e) {
    await client.query('ROLLBACK');
    console.error('PATCH tutor-response error:', e);
    return res.status(500).json({ message: 'Lỗi máy chủ.' });
  } finally {
    client.release();
  }
});

// PATCH /api/bookings/disputes/:disputeId/withdraw — học sinh tự rút đơn khiếu nại (không sửa nội dung)
app.patch('/api/bookings/disputes/:disputeId/withdraw', verifyToken, async (req, res) => {
  const client = await pool.connect();
  try {
    const dRes = await client.query('SELECT * FROM disputes WHERE id=$1', [req.params.disputeId]);
    if (!dRes.rows.length) return res.status(404).json({ message: 'Không tìm thấy khiếu nại.' });
    const dispute = dRes.rows[0];

    if (dispute.raised_by !== req.user.userId) {
      return res.status(403).json({ message: 'Bạn không có quyền rút khiếu nại này.' });
    }
    if (dispute.status !== 'OPEN' || dispute.withdrawn_at) {
      return res.status(409).json({ message: 'Khiếu nại đã được xử lý hoặc đã rút trước đó.' });
    }

    await client.query('BEGIN');
    const updated = await client.query(
      `UPDATE disputes SET withdrawn_at=NOW() WHERE id=$1 RETURNING *`,
      [req.params.disputeId]
    );

    // Booking dispute: khôi phục luồng tự động giải ngân bình thường (auto_release_at
    // chỉ từng bị đặt về NOW() khi thiếu ví lúc điểm danh — không có mốc "lessonEnd + Nh"
    // nào khác trong hệ thống — nên đặt lại NOW() để cron auto-release xử lý ở lượt kế tiếp).
    if (dispute.booking_id) {
      await client.query(
        `UPDATE bookings SET auto_release_at=NOW() WHERE id=$1 AND escrow_released_at IS NULL`,
        [dispute.booking_id]
      );
    }

    const admins = await client.query("SELECT id FROM users WHERE role='admin'");
    const reporterRes = await client.query('SELECT full_name FROM users WHERE id=$1', [dispute.raised_by]);
    const reporterName = reporterRes.rows[0]?.full_name || 'Học sinh';
    for (const admin of admins.rows) {
      await safeNotifyUser(client, {
        userId: admin.id, channels: ['IN_APP'],
        templateKey: 'dispute_withdrawn', eventType: 'dispute_withdrawn',
        data: { forAdmin: true, reporterName },
        refId: req.params.disputeId, refType: 'dispute',
        sourceType: 'dispute', sourceId: req.params.disputeId,
        idempotencyKey: `dispute:${req.params.disputeId}:withdrawn:${admin.id}`,
      });
    }
    if (dispute.tutor_id) {
      await safeNotifyUser(client, {
        userId: dispute.tutor_id, channels: ['IN_APP'],
        templateKey: 'dispute_withdrawn', eventType: 'dispute_withdrawn',
        data: { forAdmin: false },
        refId: req.params.disputeId, refType: 'dispute',
        sourceType: 'dispute', sourceId: req.params.disputeId,
        idempotencyKey: `dispute:${req.params.disputeId}:withdrawn:${dispute.tutor_id}`,
      });
    }

    await client.query('COMMIT');
    return res.json({ success: true, dispute: updated.rows[0] });
  } catch (e) {
    await client.query('ROLLBACK');
    console.error('PATCH withdraw dispute error:', e);
    return res.status(500).json({ message: 'Lỗi máy chủ.' });
  } finally {
    client.release();
  }
});

// POST /api/courses/:id/report — Học sinh / Phụ huynh báo cáo khóa học
app.post('/api/courses/:id/report', verifyToken, async (req, res) => {
  const client = await pool.connect();
  try {
    const { reason, severity = 'medium', requestedResolution } = req.body;
    if (!reason?.trim()) return res.status(400).json({ message: 'Vui lòng cung cấp lý do báo cáo.' });
    // Tương thích ngược tạm thời: route này chưa có caller frontend nào tính tới thời điểm audit Bước 8a.0,
    // nhưng vẫn chấp nhận cả evidenceUrl (string, dạng cũ) lẫn evidenceUrls (mảng, dạng mới) để không phá caller ngoài nếu có.
    const evidenceUrls = Array.isArray(req.body.evidenceUrls)
      ? req.body.evidenceUrls
      : (req.body.evidenceUrl ? [req.body.evidenceUrl] : null);
    const studentRequestedResolution = requestedResolution?.trim() || null;

    let enrollmentQuery;
    let queryParams;
    let isParent = false;

    if (req.user.role === 'parent') {
      enrollmentQuery = `
        SELECT ce.*, c.price, c.tutor_id, c.title
        FROM course_enrollments ce
        JOIN courses c ON ce.course_id = c.id
        JOIN parent_children pc ON ce.student_id = pc.student_id
        WHERE ce.course_id = $1 AND pc.parent_id = $2
      `;
      queryParams = [req.params.id, req.user.userId];
      isParent = true;
    } else {
      enrollmentQuery = `
        SELECT ce.*, c.price, c.tutor_id, c.title
        FROM course_enrollments ce
        JOIN courses c ON ce.course_id = c.id
        WHERE ce.course_id = $1 AND ce.student_id = $2
      `;
      queryParams = [req.params.id, req.user.userId];
    }

    const enrollmentRes = await client.query(enrollmentQuery, queryParams);
    if (!enrollmentRes.rows.length) return res.status(404).json({ message: 'Không tìm thấy thông tin đăng ký khóa học hoặc bạn không có quyền truy cập.' });
    const enrollment = enrollmentRes.rows[0];

    if (enrollment.status === 'refunded') return res.status(400).json({ message: 'Khóa học này đã được hoàn tiền.' });

    const existingDispute = await client.query(
      "SELECT id FROM disputes WHERE course_id=$1 AND raised_by=$2 AND status='OPEN' AND withdrawn_at IS NULL", [enrollment.course_id, req.user.userId]
    );
    if (existingDispute.rows.length) return res.status(409).json({ message: 'Bạn đã gửi khiếu nại cho khóa học này rồi.' });

    // Tránh chồng chéo với luồng khiếu nại dịch vụ (course_complaints) cho cùng khóa học —
    // xem ghi chú tương ứng ở POST /api/complaints.
    const activeServiceComplaint = await client.query(
      `SELECT id FROM course_complaints WHERE course_id=$1 AND student_id=$2 AND status NOT IN ('resolved','rejected','closed')`,
      [enrollment.course_id, enrollment.student_id]
    );
    if (activeServiceComplaint.rows.length) {
      return res.status(409).json({ message: 'Khóa học này đang có khiếu nại dịch vụ chưa xử lý xong. Vui lòng chờ khiếu nại đó được giải quyết trước khi mở tranh chấp giao dịch.' });
    }

    // ── Refund Policy v2.1: 48h window + progress-tiered rate (Batch 16) ──────
    const hoursSincePurchase = (Date.now() - new Date(enrollment.purchased_at).getTime()) / 3600000;

    const lessonsRes = await client.query("SELECT COUNT(*) FROM course_lessons WHERE course_id=$1", [enrollment.course_id]);
    const totalLessons = parseInt(lessonsRes.rows[0].count);
    const progressRes = await client.query("SELECT COUNT(*) FROM course_progress WHERE enrollment_id=$1 AND is_completed=true", [enrollment.id]);
    const completedLessons = parseInt(progressRes.rows[0].count);
    const progressPercent = totalLessons === 0 ? 0 : (completedLessons / totalLessons) * 100;

    const decision = getCourseRefundDecision(hoursSincePurchase, progressPercent);
    const price = parseFloat(enrollment.price || 0);

    await client.query('BEGIN');

    if (decision.eligible && price > 0) {
      // Reverse only refundAmount proportionally (course pays out immediately)
      const refundAmount = Math.round(price * decision.refundRate);
      const nonRefunded  = price - refundAmount;
      const tutorDeduct  = Math.round(refundAmount * 0.9);
      const adminDeduct  = refundAmount - tutorDeduct;

      const sw = await client.query('SELECT id, balance FROM wallets WHERE user_id=$1', [enrollment.student_id]);
      const tw = await client.query('SELECT id, balance FROM wallets WHERE user_id=$1', [enrollment.tutor_id]);
      const adminWalletId = await getAdminWalletId(client);
      const adminW = adminWalletId ? await client.query('SELECT balance FROM wallets WHERE id=$1', [adminWalletId]) : { rows: [] };

      // Only auto-settle if wallets exist AND have sufficient balance (CHECK balance>=0).
      // Otherwise fall through to ADMIN_REVIEW rather than corrupt balances.
      const canSettle = sw.rows.length && tw.rows.length && adminWalletId && adminW.rows.length &&
        Number(tw.rows[0].balance) >= tutorDeduct && Number(adminW.rows[0].balance) >= adminDeduct;

      if (canSettle) {
        // Idempotency + audit (UNIQUE(target,student) = atomic double-refund lock)
        const logId = await createRefundLog(client, {
          target_type: 'course', target_id: enrollment.course_id, student_id: enrollment.student_id,
          tutor_id: enrollment.tutor_id, original_amount: price, refund_rate: decision.refundRate,
          refund_amount: refundAmount, non_refunded_amount: nonRefunded, reason_code: decision.reasonCode,
          decision_by: 'system',
          metadata: { mode: decision.mode, progress_percent: Math.round(progressPercent), hours_since_purchase: Math.round(hoursSincePurchase) },
        });
        if (!logId) { await client.query('ROLLBACK'); return res.status(409).json({ message: 'Khóa học này đã được hoàn tiền.' }); }

        await setLedgerContext(client, { reason_code: 'COURSE_REFUND_POLICY_V2_1', source: 'api', reference_type: 'course', reference_id: enrollment.course_id, actor_id: req.user.userId, policy_version: REFUND_POLICY_VERSION, metadata: { refund_rate: decision.refundRate } });
        await client.query(`UPDATE wallets SET balance = balance + $1 WHERE id = $2`, [refundAmount, sw.rows[0].id]);
        if (tutorDeduct > 0) await client.query(`UPDATE wallets SET balance = balance - $1 WHERE id = $2`, [tutorDeduct, tw.rows[0].id]);
        if (adminDeduct > 0) await client.query(`UPDATE wallets SET balance = balance - $1 WHERE id = $2`, [adminDeduct, adminWalletId]);

        // Commission log: REVERSED — policy refund reverses prior commission (Batch 18)
        if (refundAmount > 0) {
          await createCommissionLog(client, {
            source_type: 'course', source_id: enrollment.course_id, course_id: enrollment.course_id,
            student_id: enrollment.student_id, tutor_id: enrollment.tutor_id,
            gross_amount: refundAmount, commission_rate: PLATFORM_COMMISSION_RATE,
            commission_amount: adminDeduct, tutor_amount: tutorDeduct,
            event_type: 'REVERSED', reason_code: 'COURSE_REFUND_POLICY_V2_1',
            decision_by: 'api', actor_id: req.user.userId,
            idempotency_key: `commission:course:${enrollment.course_id}:student:${enrollment.student_id}:COURSE_REFUND_POLICY_V2_1`,
            metadata: { refund_rate: decision.refundRate, reason_code: decision.reasonCode, progress_percent: Math.round(progressPercent), hours_since_purchase: Math.round(hoursSincePurchase) },
          });
        }

        await client.query(`UPDATE course_enrollments SET status='refunded' WHERE id=$1`, [enrollment.id]);

        await client.query(`
          INSERT INTO transactions (wallet_id, amount, type, status, gateway, reference_id, description)
          VALUES ($1,$2,'REFUND','SUCCESS','SYSTEM',$3,$4)
        `, [sw.rows[0].id, refundAmount, enrollment.course_id, `Hoàn tiền khóa học ${Math.round(decision.refundRate * 100)}% — ${decision.reasonCode}`]);

        await client.query(`
          INSERT INTO disputes (transaction_id, raised_by, reason, status, course_id, target_type, tutor_id, severity, raised_by_parent, evidence_urls, admin_note, resolved_at, student_requested_resolution)
          VALUES (NULL, $1, $2, 'RESOLVED_REFUND', $3, 'course', $4, $5, $6, $7, $8, NOW(), $9)
        `, [req.user.userId, reason.trim(), enrollment.course_id, enrollment.tutor_id, severity, isParent, evidenceUrls,
            `Tự động hoàn ${Math.round(decision.refundRate * 100)}% theo ${REFUND_POLICY_VERSION} (tiến độ ${Math.round(progressPercent)}%, ${Math.round(hoursSincePurchase)}h).`,
            studentRequestedResolution]);

        await safeNotifyUser(client, {
          userId: enrollment.student_id, channels: ['IN_APP', 'EMAIL'],
          templateKey: 'course_refunded', eventType: 'course_refunded',
          data: { amount: refundAmount, rate: decision.refundRate, courseName: enrollment.title },
          refId: enrollment.course_id, refType: 'course',
          sourceType: 'course', sourceId: enrollment.course_id,
          idempotencyKey: `course:${enrollment.course_id}:student:${enrollment.student_id}:refunded`,
        });

        await client.query('COMMIT');
        return res.status(200).json({
          message: `Đã hoàn ${refundAmount.toLocaleString('vi-VN')}đ (${Math.round(decision.refundRate * 100)}%) vào ví của bạn.`,
          refund: { rate: decision.refundRate, amount: refundAmount, reason_code: decision.reasonCode, policy_version: REFUND_POLICY_VERSION },
        });
      }
      // wallets missing / insufficient balance → fall through to ADMIN_REVIEW
    }

    // ── ADMIN_REVIEW (>80% progress, >48h, or auto-settle unsafe) → OPEN dispute
    const dispute = await client.query(`
      INSERT INTO disputes (transaction_id, raised_by, reason, status, course_id, target_type, tutor_id, severity, raised_by_parent, evidence_urls, admin_note, student_requested_resolution)
      VALUES (NULL, $1, $2, 'OPEN', $3, 'course', $4, $5, $6, $7, $8, $9) RETURNING id
    `, [req.user.userId, reason.trim(), enrollment.course_id, enrollment.tutor_id, severity, isParent, evidenceUrls,
        `Chuyển admin xét duyệt theo ${REFUND_POLICY_VERSION}: ${decision.reasonCode}.`,
        studentRequestedResolution]);

    const admins = await client.query("SELECT id FROM users WHERE role='admin'");
    const reporterName = isParent ? 'Phụ huynh' : 'Học sinh';
    for (const admin of admins.rows) {
      await safeNotifyUser(client, {
        userId: admin.id, channels: ['IN_APP', 'EMAIL'],
        templateKey: 'dispute_opened', eventType: 'dispute_opened',
        data: { forAdmin: true, reporterName, reason: `khiếu nại khóa học ID: ${enrollment.course_id}. Lý do: ${reason}` },
        refId: dispute.rows[0].id, refType: 'dispute',
        sourceType: 'dispute', sourceId: dispute.rows[0].id,
        idempotencyKey: `dispute:${dispute.rows[0].id}:opened:${admin.id}`,
      });
    }
    if (enrollment.tutor_id) {
      await safeNotifyUser(client, {
        userId: enrollment.tutor_id, channels: ['IN_APP', 'EMAIL'],
        templateKey: 'dispute_opened', eventType: 'dispute_opened',
        data: { forAdmin: false, reporterName },
        refId: dispute.rows[0].id, refType: 'dispute',
        sourceType: 'dispute', sourceId: dispute.rows[0].id,
        idempotencyKey: `dispute:${dispute.rows[0].id}:opened:${enrollment.tutor_id}`,
      });
    }

    await client.query('COMMIT');
    return res.status(201).json({ message: 'Đã gửi báo cáo khóa học. Admin sẽ xem xét trong 24-48h.', disputeId: dispute.rows[0].id });
  } catch (e) {
    await client.query('ROLLBACK');
    console.error('Course report error:', e);
    return res.status(500).json({ message: 'Lỗi máy chủ.' });
  } finally {
    client.release();
  }
});

// ═══ AI Case Resolution endpoints (Batch 25 — dry-run scaffolding) ══════════

// POST /api/admin/ai-cases/run-pending — manually trigger a scan of pending cases.
app.post('/api/admin/ai-cases/run-pending', verifyToken, requireAdmin, async (req, res) => {
  try {
    const result = await runPendingAiCases({ triggeredBy: 'admin', adminId: req.user.id });
    return res.json({ ok: true, ...result });
  } catch (err) {
    console.error('POST /api/admin/ai-cases/run-pending error:', err.message);
    return res.status(500).json({ message: 'Không thể chạy xử lý AI cho các khiếu nại.' });
  }
});

// GET /api/admin/ai-cases — list AI case resolutions (filter + paginate).
app.get('/api/admin/ai-cases', verifyToken, requireAdmin, async (req, res) => {
  try {
    const page   = Math.max(1, parseInt(req.query.page, 10) || 1);
    const limit  = Math.min(100, Math.max(1, parseInt(req.query.limit, 10) || 50));
    const offset = (page - 1) * limit;
    const where = []; const params = [];
    if (req.query.status)       { params.push(req.query.status);       where.push(`r.status = $${params.length}`); }
    if (req.query.appealStatus) { params.push(req.query.appealStatus); where.push(`r.appeal_status = $${params.length}`); }
    const whereSql = where.length ? `WHERE ${where.join(' AND ')}` : '';

    const totalRes = await pool.query(`SELECT COUNT(*)::int AS n FROM ai_case_resolutions r ${whereSql}`, params);
    const rows = (await pool.query(
      `SELECT r.*, s.full_name AS student_name, s.email AS student_email,
              t.full_name AS tutor_name, t.email AS tutor_email,
              d.reason AS dispute_reason, d.status AS dispute_status
         FROM ai_case_resolutions r
         LEFT JOIN users s    ON s.id = r.student_id
         LEFT JOIN users t    ON t.id = r.tutor_id
         LEFT JOIN disputes d ON d.id = r.dispute_id
         ${whereSql}
         ORDER BY r.created_at DESC
         LIMIT $${params.length + 1} OFFSET $${params.length + 2}`,
      [...params, limit, offset]
    )).rows;

    const summary = { ai_suggested: 0, auto_resolved: 0, need_human_review: 0, appealed: 0 };
    for (const s of (await pool.query(`SELECT status, COUNT(*)::int AS n FROM ai_case_resolutions GROUP BY status`)).rows) {
      if (s.status === 'AI_SUGGESTED')      summary.ai_suggested      = s.n;
      else if (s.status === 'AUTO_RESOLVED') summary.auto_resolved     = s.n;
      else if (s.status === 'NEED_HUMAN_REVIEW') summary.need_human_review = s.n;
    }
    summary.appealed = (await pool.query(`SELECT COUNT(*)::int AS n FROM ai_case_resolutions WHERE appeal_status='APPEALED_NEED_REVIEW'`)).rows[0].n;

    return res.json({
      items: rows,
      pagination: { page, limit, total: totalRes.rows[0].n },
      summary,
      config: {
        resolution_enabled: AUTO_AI_RESOLUTION_ENABLED, dry_run: AUTO_AI_DRY_RUN,
        cron_enabled: AUTO_AI_CRON_ENABLED, min_case_age_hours: AI_CASE_CONFIG.minCaseAgeHours,
      },
    });
  } catch (err) {
    console.error('GET /api/admin/ai-cases error:', err.message);
    return res.status(500).json({ message: 'Không thể tải danh sách xử lý AI.' });
  }
});

// GET /api/admin/ai-cases/:id — full detail for the admin modal.
app.get('/api/admin/ai-cases/:id', verifyToken, requireAdmin, async (req, res) => {
  try {
    const r = await pool.query(
      `SELECT r.*, s.full_name AS student_name, s.email AS student_email,
              t.full_name AS tutor_name, t.email AS tutor_email, ab.full_name AS appeal_by_name,
              d.reason AS dispute_reason, d.status AS dispute_status, d.created_at AS dispute_created_at
         FROM ai_case_resolutions r
         LEFT JOIN users s    ON s.id = r.student_id
         LEFT JOIN users t    ON t.id = r.tutor_id
         LEFT JOIN users ab   ON ab.id = r.appeal_by
         LEFT JOIN disputes d ON d.id = r.dispute_id
        WHERE r.id = $1`, [req.params.id]);
    if (!r.rows.length) return res.status(404).json({ message: 'Không tìm thấy bản ghi.' });
    return res.json(r.rows[0]);
  } catch (err) {
    console.error('GET /api/admin/ai-cases/:id error:', err.message);
    return res.status(500).json({ message: 'Không thể tải chi tiết.' });
  }
});

// GET /api/my/ai-cases — the current user's own AI case resolutions.
app.get('/api/my/ai-cases', verifyToken, async (req, res) => {
  try {
    const rows = (await pool.query(
      `SELECT r.id, r.status, r.severity, r.money_action, r.recommendation, r.reason_summary,
              r.risk_flags, r.appeal_status, r.appeal_reason, r.appealed_at, r.created_at, r.resolved_at,
              d.reason AS dispute_reason,
              (r.student_id = $1) AS is_student, (r.tutor_id = $1) AS is_tutor
         FROM ai_case_resolutions r
         LEFT JOIN disputes d ON d.id = r.dispute_id
        WHERE r.student_id = $1 OR r.tutor_id = $1
        ORDER BY r.created_at DESC
        LIMIT 100`, [req.user.id])).rows;
    return res.json({ items: rows });
  } catch (err) {
    console.error('GET /api/my/ai-cases error:', err.message);
    return res.status(500).json({ message: 'Không thể tải danh sách.' });
  }
});

// POST /api/my/ai-case-feedback/:id/appeal — affected user appeals an AUTO_RESOLVED case.
app.post('/api/my/ai-case-feedback/:id/appeal', verifyToken, async (req, res) => {
  try {
    const reason = sanitizeNotificationText(req.body?.appealReason || req.body?.reason, 1000);
    if (!reason) return res.status(400).json({ message: 'Vui lòng nhập lý do kháng cáo.' });

    const r = await pool.query('SELECT * FROM ai_case_resolutions WHERE id=$1', [req.params.id]);
    if (!r.rows.length) return res.status(404).json({ message: 'Không tìm thấy quyết định AI.' });
    const rec = r.rows[0];

    // Only the affected student or tutor may appeal.
    if (![rec.student_id, rec.tutor_id].includes(req.user.id)) {
      return res.status(403).json({ message: 'Bạn không có quyền kháng cáo quyết định này.' });
    }
    // Only AUTO_RESOLVED decisions can be appealed.
    if (rec.status !== 'AUTO_RESOLVED') {
      return res.status(409).json({ message: 'Chỉ có thể kháng cáo quyết định đã tự động xử lý.' });
    }
    // Appeal window: within 24 hours after resolution.
    const base = rec.resolved_at || rec.created_at;
    if (base && (Date.now() - new Date(base).getTime()) > 24 * 60 * 60 * 1000) {
      return res.status(409).json({ message: 'Đã quá thời hạn kháng cáo (24 giờ).' });
    }
    if (rec.appeal_status !== 'NONE') {
      return res.status(409).json({ message: 'Kháng cáo đã được gửi trước đó.' });
    }

    await pool.query(
      `UPDATE ai_case_resolutions
          SET appeal_status='APPEALED_NEED_REVIEW', appeal_reason=$1, appeal_by=$2, appealed_at=NOW()
        WHERE id=$3`, [reason, req.user.id, req.params.id]);

    // Notify all admins (in-app). Never blocks the response on notification failure.
    try {
      const admins = await pool.query("SELECT id FROM users WHERE role='admin'");
      for (const a of admins.rows) {
        await createInAppNotification(pool, {
          userId: a.id, type: 'system', eventType: 'ai_case_appealed',
          title: 'Có kháng cáo quyết định AI cần xem xét',
          body: `Một người dùng đã kháng cáo quyết định AI (case ${req.params.id}).`,
          icon: 'gavel', refId: req.params.id, refType: 'ai_case', priority: 'high',
          idempotencyKey: `ai_case_appeal:${req.params.id}:${a.id}`,
        });
      }
    } catch (nErr) { console.warn('[ai-case appeal] admin notify failed:', nErr.message); }

    return res.json({ ok: true, message: 'Kháng cáo đã được gửi. Admin sẽ xem xét lại quyết định.' });
  } catch (err) {
    console.error('POST /api/my/ai-case-feedback/:id/appeal error:', err.message);
    return res.status(500).json({ message: 'Không thể gửi kháng cáo.' });
  }
});

// ═══ Admin AI Copilot endpoints (Batch 26 — advisory only) ══════════════════

// POST /api/admin/copilot/analyze — context-aware advisory analysis.
// Batch 39: pick a focus entity out of a module's lightweight pageContext, in
// priority order. Only keys that map to an EXISTING collector are honored
// (course-complaint ids have no collector, so a complaints page still falls back
// to its module summary + the booking/tutor/student it references).
function resolvePageFocus(pageContext) {
  if (!pageContext || typeof pageContext !== 'object') return null;
  const pick = v => (v != null && String(v).trim() !== '') ? String(v).trim() : null;
  const alertId = pick(pageContext.alertId);
  const disputeId = pick(pageContext.disputeId);
  const bookingId = pick(pageContext.bookingId);
  const transactionId = pick(pageContext.transactionId || pageContext.selectedTransaction);
  const tutorId = pick(pageContext.tutorId);
  const studentId = pick(pageContext.studentId);
  if (alertId) return { type: 'FRAUD_ALERT', id: alertId };
  if (disputeId) return { type: 'DISPUTE', id: disputeId };
  if (bookingId) return { type: 'BOOKING', id: bookingId };
  if (transactionId) return { type: 'TRANSACTION', id: transactionId };
  if (tutorId) return { type: 'TUTOR', id: tutorId };
  if (studentId) return { type: 'STUDENT', id: studentId };
  return null;
}

app.post('/api/admin/copilot/analyze', verifyToken, requireAdmin, async (req, res) => {
  try {
    const { entityType, entityId, pageKey, pageContext } = req.body || {};
    const type = String(entityType || 'PAGE').toUpperCase();
    const allowed = ['TUTOR', 'STUDENT', 'DISPUTE', 'TRANSACTION', 'BOOKING', 'FRAUD_ALERT', 'PAGE'];
    if (!allowed.includes(type)) return res.status(400).json({ message: 'entityType không hợp lệ.' });
    if (type !== 'PAGE' && !entityId) return res.status(400).json({ message: 'Thiếu entityId cho loại đối tượng này.' });

    let context, reportType = type;
    if (type === 'TUTOR')            context = await collectTutorCopilotContext(entityId);
    else if (type === 'STUDENT')     context = await collectStudentCopilotContext(entityId);
    else if (type === 'DISPUTE')     context = await collectDisputeCopilotContext(entityId);
    else if (type === 'BOOKING')     context = await collectBookingCopilotContext(entityId);
    else if (type === 'TRANSACTION') context = await collectTransactionCopilotContext(entityId);
    else if (type === 'FRAUD_ALERT') context = await collectFraudAlertCopilotContext(entityId);
    else {
      // PAGE — if the module sent a selected entity id, analyze that entity
      // (Batch 39, PART 3) reusing the existing collectors; otherwise fall back
      // to the module summary. Either way, tag with the module so the workflow
      // and navigation reflect the page the admin is on.
      const focus = resolvePageFocus(pageContext);
      const collectors = {
        TUTOR: collectTutorCopilotContext, STUDENT: collectStudentCopilotContext,
        DISPUTE: collectDisputeCopilotContext, BOOKING: collectBookingCopilotContext,
        TRANSACTION: collectTransactionCopilotContext, FRAUD_ALERT: collectFraudAlertCopilotContext,
      };
      if (focus && collectors[focus.type]) {
        const focused = await collectors[focus.type](focus.id);
        if (focused.notes?.includes('NOT_FOUND')) {
          context = await collectPageCopilotContext(pageKey, pageContext); // graceful fallback
        } else {
          context = focused;
          reportType = focus.type;
        }
      } else {
        context = await collectPageCopilotContext(pageKey, pageContext);
      }
      context.module = copilotModuleForPageKey(pageKey);
      context.page_key = pageKey || null;
    }

    const report = generateAdminCopilotReport(reportType, context);
    const llm = await maybeCopilotLLMRewrite(report, context);
    report.summary = llm.summary;
    report.model_used = llm.model_used;
    report.created_at = new Date().toISOString();

    let savedId = null;
    try {
      const ins = await pool.query(
        `INSERT INTO admin_copilot_reports
           (entity_type, entity_id, page_key, summary, confidence, risk_level,
            key_findings, evidence, recommendations, suggested_admin_actions, limitations,
            model_used, input_snapshot, created_by)
         VALUES ($1,$2,$3,$4,$5,$6,$7::jsonb,$8::jsonb,$9::jsonb,$10::jsonb,$11::jsonb,$12,$13::jsonb,$14)
         RETURNING id`,
        [
          reportType, context.entity_id != null ? String(context.entity_id) : (entityId ? String(entityId) : null), pageKey || null, report.summary,
          report.confidence, report.risk_level,
          JSON.stringify(report.key_findings), JSON.stringify(report.evidence),
          JSON.stringify(report.recommendations), JSON.stringify(report.suggested_admin_actions),
          JSON.stringify(report.limitations), report.model_used,
          JSON.stringify(sanitizeCopilotSnapshot(context)), req.user.id,
        ]
      );
      savedId = ins.rows[0].id;
    } catch (e) { console.warn('[copilot] persist failed:', e.message); }

    return res.json({ id: savedId, ...report });
  } catch (err) {
    console.error('POST /api/admin/copilot/analyze error:', err.message);
    return res.status(500).json({ message: 'Không thể phân tích ngữ cảnh.' });
  }
});

// GET /api/admin/copilot/history — recent analyses (filterable, paginated).
app.get('/api/admin/copilot/history', verifyToken, requireAdmin, async (req, res) => {
  try {
    const page   = Math.max(1, parseInt(req.query.page, 10) || 1);
    const limit  = Math.min(100, Math.max(1, parseInt(req.query.limit, 10) || 30));
    const offset = (page - 1) * limit;
    const where = []; const params = [];
    if (req.query.entityType) { params.push(String(req.query.entityType).toUpperCase()); where.push(`entity_type = $${params.length}`); }
    if (req.query.entityId)   { params.push(String(req.query.entityId)); where.push(`entity_id = $${params.length}`); }
    if (req.query.riskLevel)  { params.push(String(req.query.riskLevel).toUpperCase()); where.push(`risk_level = $${params.length}`); }
    if (req.query.from)       { params.push(req.query.from); where.push(`created_at >= $${params.length}`); }
    if (req.query.to)         { params.push(req.query.to);   where.push(`created_at <= $${params.length}`); }
    const whereSql = where.length ? `WHERE ${where.join(' AND ')}` : '';

    const total = await copilotSafeCount(`SELECT COUNT(*)::int AS n FROM admin_copilot_reports ${whereSql}`, params);
    const rows = await copilotSafeRows(
      `SELECT id, entity_type, entity_id, page_key, summary, confidence, risk_level,
              model_used, created_at
         FROM admin_copilot_reports ${whereSql}
         ORDER BY created_at DESC
         LIMIT $${params.length + 1} OFFSET $${params.length + 2}`,
      [...params, limit, offset]
    );
    return res.json({ items: rows, pagination: { page, limit, total } });
  } catch (err) {
    console.error('GET /api/admin/copilot/history error:', err.message);
    return res.status(500).json({ message: 'Không thể tải lịch sử phân tích.' });
  }
});

