  // ── Auto-migrate: wallet deposit/withdraw requests (Batch 36 — bug fix) ─────
  // These tables previously only existed via a standalone .sql file that was
  // never actually run by startServer(), so create them here for consistency.
  // Bug fix: admin approve for withdraw_requests sets status='APPROVED' as an
  // intermediate step (tutor must self-confirm receipt before COMPLETED — see
  // adminWalletRoutes.js / walletRoutes.js), but the live status CHECK
  // constraint only allowed PENDING/COMPLETED/REJECTED, so every approval
  // attempt failed and requests were stuck at PENDING forever. Widen it.
  try {
    await pool.query(`
      CREATE TABLE IF NOT EXISTS deposit_requests (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        wallet_id UUID NOT NULL REFERENCES wallets(id),
        amount NUMERIC(15,2) NOT NULL CHECK (amount > 0),
        method TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'COMPLETED', 'REJECTED')),
        admin_note TEXT,
        created_at TIMESTAMPTZ DEFAULT NOW(),
        updated_at TIMESTAMPTZ DEFAULT NOW()
      );
      CREATE TABLE IF NOT EXISTS withdraw_requests (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        wallet_id UUID NOT NULL REFERENCES wallets(id),
        amount NUMERIC(15,2) NOT NULL CHECK (amount > 0),
        method TEXT NOT NULL,
        account_details JSONB,
        status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'APPROVED', 'COMPLETED', 'REJECTED')),
        admin_note TEXT,
        created_at TIMESTAMPTZ DEFAULT NOW(),
        updated_at TIMESTAMPTZ DEFAULT NOW()
      );
    `);
    await pool.query(`ALTER TABLE withdraw_requests DROP CONSTRAINT IF EXISTS withdraw_requests_status_check`);
    await pool.query(`ALTER TABLE withdraw_requests ADD CONSTRAINT withdraw_requests_status_check CHECK (status IN ('PENDING', 'APPROVED', 'COMPLETED', 'REJECTED'))`);
    console.log('✅ DB migration: deposit_requests + withdraw_requests ready, APPROVED status allowed (Batch 36)');
  } catch (err) {
    console.error('⚠️  DB migration (wallet deposit/withdraw requests Batch 36) warning:', err.message);
  }

  // ── Auto-migrate: Reconciliation Investigation Center (Batch 37) ───────────
  // Reconciliation checks/items are computed live (see computeReconciliation(),
  // never persisted) — same design as fraud_investigations (Batch 35). finding_key
  // is deterministic ("check:<check-id>" | "item:<item-id>"), so investigation
  // state can key off it safely. reconciliation_runs stores explicit, admin-
  // triggered snapshots only (POST /reconciliation/run) — the passive GET never
  // writes here, so simply viewing the page can never inflate run history.
  try {
    await pool.query(`
      CREATE TABLE IF NOT EXISTS reconciliation_investigations (
        finding_key     TEXT PRIMARY KEY,
        finding_type    TEXT NOT NULL CHECK (finding_type IN ('check','item')),
        status          TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','INVESTIGATING','RESOLVED','CLOSED')),
        severity        TEXT,
        last_difference NUMERIC(15,2),
        root_cause      TEXT,
        confidence      INT,
        ai_summary      TEXT,
        ai_model_used   TEXT,
        assigned_to     UUID REFERENCES users(id) ON DELETE SET NULL,
        reviewed_by     UUID REFERENCES users(id) ON DELETE SET NULL,
        reviewed_at     TIMESTAMPTZ,
        created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
      );

      CREATE TABLE IF NOT EXISTS reconciliation_audit_logs (
        id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        finding_key     TEXT NOT NULL,
        action          TEXT NOT NULL,
        admin_id        UUID REFERENCES users(id) ON DELETE SET NULL,
        previous_status TEXT,
        new_status      TEXT,
        reason          TEXT,
        ip_address      TEXT,
        created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
      );
      CREATE INDEX IF NOT EXISTS idx_recon_audit_finding ON reconciliation_audit_logs(finding_key);

      CREATE TABLE IF NOT EXISTS reconciliation_incidents (
        id                       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        finding_key              TEXT,
        title                    TEXT NOT NULL,
        description              TEXT,
        difference_amount        NUMERIC(15,2),
        root_cause               TEXT,
        related_booking_id       UUID,
        related_transaction_ids  UUID[] DEFAULT '{}',
        severity                 TEXT NOT NULL DEFAULT 'MEDIUM' CHECK (severity IN ('INFO','LOW','MEDIUM','HIGH','CRITICAL')),
        assigned_developer       TEXT,
        status                   TEXT NOT NULL DEFAULT 'Open' CHECK (status IN ('Open','Investigating','Resolved','Closed')),
        created_by               UUID REFERENCES users(id) ON DELETE SET NULL,
        created_at               TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        updated_at               TIMESTAMPTZ NOT NULL DEFAULT NOW()
      );
      CREATE INDEX IF NOT EXISTS idx_recon_incidents_finding ON reconciliation_incidents(finding_key);
      CREATE INDEX IF NOT EXISTS idx_recon_incidents_status  ON reconciliation_incidents(status);

      CREATE TABLE IF NOT EXISTS reconciliation_incident_comments (
        id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        incident_id UUID NOT NULL REFERENCES reconciliation_incidents(id) ON DELETE CASCADE,
        admin_id    UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        content     TEXT NOT NULL,
        created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
      );

      CREATE TABLE IF NOT EXISTS reconciliation_runs (
        id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        status           TEXT NOT NULL,
        difference_count INT NOT NULL DEFAULT 0,
        issue_count      INT NOT NULL DEFAULT 0,
        duration_ms      INT,
        performed_by     UUID REFERENCES users(id) ON DELETE SET NULL,
        snapshot         JSONB NOT NULL,
        created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
      );
      CREATE INDEX IF NOT EXISTS idx_recon_runs_created ON reconciliation_runs(created_at);
    `);
    console.log('✅ DB migration: reconciliation_investigations/_audit_logs/_incidents/_incident_comments/_runs ready (Batch 37)');
  } catch (err) {
    console.error('⚠️  DB migration (Reconciliation Investigation Center Batch 37) warning:', err.message);
  }

  // Prime the dynamic subject index so admin-created subjects resolve from the
  // first request onward, not only after the next mutation (Batch 33).
  await refreshSubjectIndex();

  // ── Cron: Email outbox processor (Batch 20) ─────────────────────────────────
  // Runs every minute; processNotificationOutbox() guards against overlap and
  // never throws, so this interval can never crash the server.
  setInterval(() => {
    processNotificationOutbox(20).catch(err => console.error('[outbox cron] error:', err.message));
  }, 60 * 1000);

  // ── Cron: Auto-release escrow sau 24h nếu không có khiếu nại ───────────────
  setInterval(async () => {
    try {
      // Lấy các booking đã mark present, đã qua auto_release_at, chưa giải ngân
      const due = await pool.query(`
        SELECT b.id, b.escrow_tx_id, b.payer_wallet_id, b.lesson_fee, b.tutor_id
        FROM bookings b
        JOIN attendance a ON a.booking_id = b.id
        WHERE b.status = 'Approved'
          AND a.status = 'present'
          AND b.escrow_released_at IS NULL
          AND b.escrow_tx_id IS NOT NULL
          AND b.auto_release_at IS NOT NULL
          AND b.auto_release_at <= NOW()
          AND NOT EXISTS (
            SELECT 1 FROM disputes d WHERE d.booking_id = b.id AND d.status = 'OPEN' AND d.withdrawn_at IS NULL
          )
      `);

      for (const row of due.rows) {
        // Batch 17: run each release in a transaction with ledger context
        const client = await pool.connect();
        try {
          const tw = await client.query('SELECT id FROM wallets WHERE user_id=$1', [row.tutor_id]);
          if (!tw.rows.length) { client.release(); continue; }
          const tutorWalletId = tw.rows[0].id;

          let adminWalletId = process.env.ADMIN_WALLET_ID;
          if (!adminWalletId) {
            const aw = await client.query("SELECT w.id FROM wallets w JOIN users u ON w.user_id=u.id WHERE u.role='admin' LIMIT 1");
            if (!aw.rows.length) { client.release(); continue; }
            adminWalletId = aw.rows[0].id;
          }

          await client.query('BEGIN');
          await setLedgerContext(client, { reason_code: 'AUTO_RELEASE_24H', source: 'cron', reference_type: 'booking', reference_id: row.id, transaction_id: row.escrow_tx_id });
          await client.query('SELECT release_escrow($1,$2,$3,$4,$5,$6)', [
            row.escrow_tx_id, row.payer_wallet_id, tutorWalletId, adminWalletId, row.lesson_fee, 0.1
          ]);
          // Commission log: EARNED on auto-release (Batch 18)
          const _arSplit = calculateCommissionSplit(row.lesson_fee);
          const _arStudent = (await client.query('SELECT student_id FROM bookings WHERE id=$1', [row.id])).rows[0]?.student_id || null;
          await createCommissionLog(client, {
            source_type: 'booking', source_id: row.id, booking_id: row.id,
            transaction_id: row.escrow_tx_id,
            student_id: _arStudent, tutor_id: row.tutor_id,
            gross_amount: _arSplit.grossAmount, commission_rate: _arSplit.commissionRate,
            commission_amount: _arSplit.commissionAmount, tutor_amount: _arSplit.tutorAmount,
            event_type: 'EARNED', reason_code: 'AUTO_RELEASE_24H',
            decision_by: 'cron',
            idempotency_key: `commission:booking:${row.id}:AUTO_RELEASE_24H`,
            metadata: { lesson_fee: row.lesson_fee },
          });
          await client.query(`UPDATE bookings SET escrow_released_at=NOW() WHERE id=$1`, [row.id]);
          await client.query(`
            UPDATE tutor_profiles SET completed_lessons_count = completed_lessons_count + 1
            WHERE user_id = $1
          `, [row.tutor_id]);
          await safeNotifyUser(client, {
            userId: row.tutor_id, channels: ['IN_APP', 'EMAIL'],
            templateKey: 'escrow_released', eventType: 'escrow_released',
            body: 'Học phí buổi học đã được chuyển vào ví của bạn (sau 24h xác nhận).',
            data: { amount: row.lesson_fee }, refId: row.id, refType: 'booking',
            sourceType: 'booking', sourceId: row.id,
            idempotencyKey: `booking:${row.id}:escrow_released:${row.tutor_id}`,
          });
          await client.query('COMMIT');
          console.log(`✅ Auto-released escrow for booking ${row.id}`);
        } catch (innerErr) {
          await client.query('ROLLBACK').catch(() => {});
          console.error(`❌ Auto-release failed for booking ${row.id}:`, innerErr.message);
        } finally {
          client.release();
        }
      }
    } catch (err) {
      if (err.code !== 'ENOTFOUND' && err.code !== 'EAI_AGAIN') {
        console.error('❌ Cron auto-release error:', err.message);
      }
    }
  }, 5 * 60 * 1000); // chạy mỗi 5 phút


  // ── Cron: Nhắc lịch trước buổi học (mốc 24h và 1h, cho cả 2 phía) ────────
  setInterval(async () => {
    try {
      const due = await pool.query(`
        SELECT b.id, b.student_id, b.tutor_id, b.tutor_name, b.subject,
               b.lesson_date, b.time_slot, b.teaching_method, b.meeting_link, b.location,
               b.reminded_24h_at, b.reminded_1h_at,
               u.full_name AS student_name
        FROM bookings b
        LEFT JOIN users u ON u.id = b.student_id
        WHERE b.status = 'Approved'
          AND b.lesson_date BETWEEN CURRENT_DATE - 1 AND CURRENT_DATE + 2
          AND (b.reminded_24h_at IS NULL OR b.reminded_1h_at IS NULL)
      `);

      const now = new Date();
      for (const b of due.rows) {
        const start = lessonStartFrom(b.lesson_date, b.time_slot);
        if (!start || start <= now) continue;
        const msLeft = start - now;
        const dateStr = lessonDateStr(b.lesson_date);
        const methodTxt = b.teaching_method === 'online'
          ? (b.meeting_link ? `Học Online — link: ${b.meeting_link}` : 'Học Online — gia sư sẽ gửi link phòng học trước giờ.')
          : b.teaching_method === 'offline'
            ? (b.location ? `Học Offline tại: ${b.location}.` : 'Học Offline — địa điểm xem trong ghi chú hoặc tin nhắn.')
            : '';
        const missingLinkWarn = b.teaching_method === 'online' && !b.meeting_link;

        // In-app + email qua notifyUser; idempotency theo booking+mốc giờ+người
        // nhận (claim UPDATE bên dưới vẫn là hàng rào chính chống gửi trùng)
        const send = (userId, hoursLeft, forTutor, message, meetLink) => safeNotifyUser(pool, {
          userId, type: 'lesson_reminder',
          channels: ['IN_APP', 'EMAIL'],
          templateKey: 'lesson_reminder', eventType: 'lesson_reminder',
          refId: b.id, refType: 'booking',
          idempotencyKey: `lesson_reminder:${b.id}:${hoursLeft}h:${userId}`,
          data: { hoursLeft, forTutor, message, meetLink: meetLink || null },
        });

        // Claim TRƯỚC khi gửi (UPDATE có điều kiện) — chống gửi trùng khi có
        // 2 process cùng chạy (nodemon restart race / bind trùng cổng trên Windows)
        if (!b.reminded_1h_at && msLeft <= 60 * 60 * 1000) {
          const claim = await pool.query(
            `UPDATE bookings SET reminded_1h_at = NOW(), reminded_24h_at = COALESCE(reminded_24h_at, NOW())
             WHERE id = $1 AND reminded_1h_at IS NULL RETURNING id`,
            [b.id]
          );
          if (!claim.rowCount) continue;
          if (b.student_id) await send(b.student_id, 1, false,
            `Buổi học ${b.subject || ''} với ${b.tutor_name || 'gia sư'} lúc ${b.time_slot} ngày ${dateStr}. ${methodTxt}`.trim(),
            b.teaching_method === 'online' ? b.meeting_link : null);
          if (b.tutor_id) await send(b.tutor_id, 1, true,
            `Buổi dạy ${b.subject || ''} với học sinh ${b.student_name || ''} lúc ${b.time_slot} ngày ${dateStr}.${missingLinkWarn ? ' ⚠️ Chưa gắn link phòng học — hãy vào Lịch trình gắn ngay!' : ''}`,
            b.teaching_method === 'online' ? b.meeting_link : null);
          console.log(`🔔 Reminder 1h sent for booking ${b.id}`);
        } else if (!b.reminded_24h_at && msLeft <= 24 * 60 * 60 * 1000) {
          const claim = await pool.query(
            `UPDATE bookings SET reminded_24h_at = NOW()
             WHERE id = $1 AND reminded_24h_at IS NULL RETURNING id`,
            [b.id]
          );
          if (!claim.rowCount) continue;
          if (b.student_id) await send(b.student_id, 24, false,
            `Ngày ${dateStr} lúc ${b.time_slot} bạn có buổi học ${b.subject || ''} với ${b.tutor_name || 'gia sư'}. ${methodTxt}`.trim(),
            b.teaching_method === 'online' ? b.meeting_link : null);
          if (b.tutor_id) await send(b.tutor_id, 24, true,
            `Ngày ${dateStr} lúc ${b.time_slot} bạn có buổi dạy ${b.subject || ''} với học sinh ${b.student_name || ''}.${missingLinkWarn ? ' Nhớ gắn link phòng học trong Lịch trình → bấm vào buổi học.' : ''}`,
            b.teaching_method === 'online' ? b.meeting_link : null);
          console.log(`🔔 Reminder 24h sent for booking ${b.id}`);
        }
      }
    } catch (err) {
      if (err.code !== 'ENOTFOUND' && err.code !== 'EAI_AGAIN') {
        console.error('❌ Cron lesson-reminder error:', err.message);
      }
    }
  }, 5 * 60 * 1000); // chạy mỗi 5 phút


  // ── Cron: Tự động hủy lịch nếu Gia sư không duyệt sau 24h ───────────────
  setInterval(async () => {
    try {
      // Tìm bookings Pending > 24h
      const dueBookings = await pool.query(`
        SELECT b.id, b.student_id, b.tutor_id, b.escrow_tx_id, b.payer_wallet_id, b.lesson_fee
        FROM bookings b
        WHERE b.status = 'Pending'
          AND b.created_at <= NOW() - INTERVAL '24 hours'
      `);

      for (const row of dueBookings.rows) {
        // Batch 16.1: wrap each booking in a transaction; refund_logs guard
        const client = await pool.connect();
        try {
          await client.query('BEGIN');
          let refunded = false;

          if (row.escrow_tx_id && Number(row.lesson_fee) > 0) {
            const fee = Number(row.lesson_fee);
            // Idempotency guard — skip refund if already refunded for this booking
            const logId = await createRefundLog(client, {
              target_type: 'booking', target_id: row.id, student_id: row.student_id,
              tutor_id: row.tutor_id, original_amount: fee, refund_rate: 1.0,
              refund_amount: fee, non_refunded_amount: 0, reason_code: 'AUTO_CANCEL_TUTOR_NO_RESPONSE',
              decision_by: 'system', metadata: { source: 'cron_auto_cancel' },
            });
            if (logId) {
              await setLedgerContext(client, { reason_code: 'AUTO_CANCEL_TUTOR_NO_RESPONSE', source: 'cron', reference_type: 'booking', reference_id: row.id, transaction_id: row.escrow_tx_id });
              await client.query('SELECT refund_escrow($1,$2,$3)', [row.escrow_tx_id, row.payer_wallet_id, fee]);
              refunded = true;
            }
            await client.query(`UPDATE bookings SET status='Cancelled', escrow_released_at=NOW() WHERE id=$1`, [row.id]);
          } else {
            // Hủy không hoàn tiền
            await client.query(`UPDATE bookings SET status='Cancelled' WHERE id=$1`, [row.id]);
          }

          // Thông báo cho Học sinh (Batch 20.1: safeNotifyUser, same client)
          await safeNotifyUser(client, {
            userId: row.student_id, type: 'refund', channels: ['IN_APP'],
            templateKey: 'booking_auto_cancel_no_response', eventType: 'booking_auto_cancel_no_response',
            title: 'Lịch học đã bị hủy do gia sư không phản hồi',
            body: refunded
              ? `Hệ thống đã hủy lịch học và hoàn lại ${Number(row.lesson_fee || 0).toLocaleString('vi-VN')}đ vì gia sư không duyệt trong 24h.`
              : `Hệ thống đã hủy lịch học vì gia sư không duyệt trong 24h.`,
            icon: 'undo', refId: row.id, refType: 'booking',
            sourceType: 'booking', sourceId: row.id, priority: 'high',
            idempotencyKey: `booking:${row.id}:auto_cancel_no_response:${row.student_id}`,
          });

          // Thông báo cho Gia sư
          await safeNotifyUser(client, {
            userId: row.tutor_id, type: 'cancellation', channels: ['IN_APP'],
            templateKey: 'booking_auto_cancel_no_response', eventType: 'booking_auto_cancel_no_response',
            title: 'Lịch học bị hủy tự động',
            body: 'Một lịch học đã bị hủy vì bạn không phản hồi trong 24h.',
            icon: 'event_busy', refId: row.id, refType: 'booking',
            sourceType: 'booking', sourceId: row.id, priority: 'high',
            idempotencyKey: `booking:${row.id}:auto_cancel_no_response:${row.tutor_id}`,
          });

          await client.query('COMMIT');
          console.log(`✅ Auto-cancelled unapproved booking ${row.id}`);
        } catch (innerErr) {
          await client.query('ROLLBACK');
          console.error(`❌ Auto-cancel failed for booking ${row.id}:`, innerErr.message);
        } finally {
          client.release();
        }
      }
    } catch (err) {
      if (err.code !== 'ENOTFOUND' && err.code !== 'EAI_AGAIN') {
        console.error('❌ Cron auto-cancel error:', err.message);
      }
    }
  }, 10 * 60 * 1000); // chạy mỗi 10 phút

  // ── Cron: AI case resolution (Batch 25) — hourly, gated OFF by default ───────
  // Uses the SAME runPendingAiCases() logic as POST /api/admin/ai-cases/run-pending.
  // Never moves money (dry-run scaffolding). Disabled unless AUTO_AI_CRON_ENABLED=true.
  if (AUTO_AI_CRON_ENABLED) {
    setInterval(() => {
      runPendingAiCases({ triggeredBy: 'cron' }).catch(err => console.error('[ai-cases cron] error:', err.message));
    }, 60 * 60 * 1000);
    console.log(`🕐 AI case cron ENABLED (hourly). resolutionEnabled=${AUTO_AI_RESOLUTION_ENABLED} dryRun=${AUTO_AI_DRY_RUN}`);
  } else {
    console.log('⏸️  AI case cron disabled (AUTO_AI_CRON_ENABLED=false).');
  }

  // ── Worker: Semantic moderation (Batch 27) — gated OFF by default ───────────
  // Uses the SAME runPendingSemanticModeration() as POST run-pending. Only writes
  // moderation reports + tutor semantic scores; never emails/bans/changes money.
  if (SEMANTIC_MODERATION_WORKER_ENABLED) {
    setInterval(() => {
      runPendingSemanticModeration({ limit: SEMANTIC_MODERATION_BATCH_LIMIT, triggeredBy: 'worker' })
        .catch(err => console.error('[semantic worker] error:', err.message));
    }, Math.max(5, SEMANTIC_MODERATION_INTERVAL_MINUTES) * 60 * 1000);
    console.log(`🕐 Semantic moderation worker ENABLED (every ${SEMANTIC_MODERATION_INTERVAL_MINUTES}m).`);
  } else {
    console.log('⏸️  Semantic moderation worker disabled (SEMANTIC_MODERATION_WORKER_ENABLED=false).');
  }

  // ── Worker: Fraud intel (Batch 28) — gated OFF by default ───────────────────
  // Same runFraudRingDetection() as POST run. Only writes fraud reports + run
  // logs; never emails/bans/moves money/changes account or transaction status.
  if (FRAUD_INTEL_WORKER_ENABLED) {
    setInterval(() => {
      runFraudRingDetection({ periodDays: FRAUD_INTEL_PERIOD_DAYS, limit: FRAUD_INTEL_BATCH_LIMIT, triggeredBy: 'worker' })
        .catch(err => console.error('[fraud worker] error:', err.message));
    }, Math.max(10, FRAUD_INTEL_INTERVAL_MINUTES) * 60 * 1000);
    console.log(`🕐 Fraud intel worker ENABLED (every ${FRAUD_INTEL_INTERVAL_MINUTES}m).`);
  } else {
    console.log('⏸️  Fraud intel worker disabled (FRAUD_INTEL_WORKER_ENABLED=false).');
  }

  // ==========================================
  // ADVANCED FEATURES APIs
  // ==========================================

  // --- Milestones ---
  app.post('/api/milestones', verifyToken, requireTutor, async (req, res) => {
    try {
      const { class_id, title, target_date } = req.body;
      const result = await pool.query(
        `INSERT INTO milestones (class_id, tutor_id, title, target_date) VALUES ($1, $2, $3, $4) RETURNING *`,
        [class_id, req.user.userId || req.user.id, title, target_date]
      );
      res.json({ message: "Milestone created", data: result.rows[0] });
    } catch (e) {
      res.status(500).json({ error: e.message });
    }
  });

  app.get('/api/milestones/:class_id', verifyToken, async (req, res) => {
    try {
      const result = await pool.query(`SELECT * FROM milestones WHERE class_id = $1 ORDER BY created_at ASC`, [req.params.class_id]);
      res.json({ data: result.rows });
    } catch (e) {
      res.status(500).json({ error: e.message });
    }
  });

  app.put('/api/milestones/:id/complete', verifyToken, requireTutor, async (req, res) => {
    try {
      const { id } = req.params;
      const evidenceCheck = await pool.query(`SELECT count(*) FROM evidences WHERE milestone_id = $1`, [id]);
      if (parseInt(evidenceCheck.rows[0].count) === 0) {
        return res.status(400).json({ error: "Bắt buộc phải có ít nhất 1 minh chứng (evidence) để hoàn thành chặng này." });
      }
      const result = await pool.query(`UPDATE milestones SET status = 'done', updated_at = NOW() WHERE id = $1 RETURNING *`, [id]);
      res.json({ message: "Milestone marked as done", data: result.rows[0] });
    } catch (e) {
      res.status(500).json({ error: e.message });
    }
  });

  // --- Evidences ---
  app.post('/api/evidences', verifyToken, requireTutor, async (req, res) => {
    try {
      const { milestone_id, file_url, file_type, description } = req.body;
      const result = await pool.query(
        `INSERT INTO evidences (milestone_id, file_url, file_type, description) VALUES ($1, $2, $3, $4) RETURNING *`,
        [milestone_id, file_url, file_type, description]
      );
      res.json({ message: "Evidence uploaded", data: result.rows[0] });
    } catch (e) {
      res.status(500).json({ error: e.message });
    }
  });

  // --- Predictive Trend ---
  app.get('/api/students/:id/predictive-trend', verifyToken, async (req, res) => {
    try {
      const studentId = req.params.id;
      const result = await pool.query(`
        SELECT understanding_level FROM lesson_feedbacks
        WHERE student_id = $1 ORDER BY created_at DESC LIMIT 5
      `, [studentId]);
      
      const feedbacks = result.rows;
      if (feedbacks.length < 3) {
        return res.json({ data: { status: 'Gathering Data', score: null, message: 'Đang thu thập dữ liệu. Cần ít nhất 3 buổi học.' } });
      }

      // Time-weighted: latest is most heavily weighted
      let score = 0;
      let totalWeight = 0;
      feedbacks.forEach((fb, index) => {
         const weight = 5 - index; // Latest = 5, oldest = 1
         totalWeight += weight;
         if (fb.understanding_level === 'Tốt') score += weight * 1;
         else if (fb.understanding_level === 'Tạm') score += weight * 0.5;
         else score += weight * 0;
      });
      const trendScore = score / totalWeight; // 0.0 to 1.0

      let status = 'Green';
      let message = 'Đúng tiến độ, con đang học rất tốt!';
      if (trendScore < 0.5) {
         status = 'Red';
         message = 'Cần can thiệp! Tốc độ học hiện tại chưa đạt yêu cầu.';
      } else if (trendScore < 0.75) {
         status = 'Yellow';
         message = 'Chậm nhẹ. Cần cố gắng hơn ở các bài tiếp theo.';
      }

      res.json({ data: { status, score: trendScore, message } });
    } catch (e) {
      res.status(500).json({ error: e.message });
    }
  });

  // --- Parent Pulse Check ---
  app.post('/api/parent-feedbacks', verifyToken, async (req, res) => {
    try {
      const { student_id, tutor_id, course_id, evaluation } = req.body;
      const result = await pool.query(
        `INSERT INTO parent_feedbacks (student_id, tutor_id, course_id, evaluation) VALUES ($1, $2, $3, $4) RETURNING *`,
        [student_id, tutor_id, course_id, evaluation]
      );

      if (evaluation === 'Không đổi' || evaluation === 'Kém đi') {
        const tutorFbs = await pool.query(`
          SELECT understanding_level FROM lesson_feedbacks 
          WHERE student_id = $1 AND tutor_id = $2 
          ORDER BY created_at DESC LIMIT 4
        `, [student_id, tutor_id]);
        
        const totCount = tutorFbs.rows.filter(f => f.understanding_level === 'Tốt').length;
        if (tutorFbs.rows.length > 0 && (totCount / tutorFbs.rows.length) > 0.75) {
           await pool.query(`
             INSERT INTO notifications (user_id, title, message, type)
             VALUES ((SELECT id FROM users WHERE role = 'admin' LIMIT 1), 'Cảnh báo Lệch Pha', 'Phụ huynh báo Kém nhưng Gia sư báo Tốt.', 'alert')
           `).catch(console.error);
        }
      }
      res.json({ message: "Cảm ơn bạn đã đánh giá!", data: result.rows[0] });
    } catch (e) {
      res.status(500).json({ error: e.message });
    }
  });

  // --- Dispute Center ---
  app.post('/api/disputes', verifyToken, async (req, res) => {
    try {
      const { session_id, reason } = req.body;
      const parent_id = req.user.userId || req.user.id;
      const result = await pool.query(
        `INSERT INTO disputes (session_id, parent_id, reason) VALUES ($1, $2, $3) RETURNING *`,
        [session_id, parent_id, reason]
      );
      res.json({ message: "Báo cáo sự cố thành công. Chúng tôi đang tạm giữ tiền và sẽ liên hệ lại.", data: result.rows[0] });
    } catch (e) {
      res.status(500).json({ error: e.message });
    }
  });


  // --- TUTOR DISPUTES & APPEALS ---
app.get('/api/tutor/disputes', verifyToken, requireTutor, async (req, res) => {
  const tutorId = req.user.userId;
  const client = await pool.connect();
  try {
    const query = `
      SELECT d.*, 
             u.full_name as student_name, 
             c.title as course_title
      FROM disputes d
      LEFT JOIN users u ON d.raised_by = u.id
      LEFT JOIN courses c ON d.course_id = c.id
      WHERE d.tutor_id = $1
      ORDER BY d.created_at DESC
    `;
    const result = await client.query(query, [tutorId]);
    res.json(result.rows);
  } catch (error) {
    console.error('Error fetching tutor disputes:', error);
    res.status(500).json({ error: 'Lỗi máy chủ' });
  } finally {
    client.release();
  }
});

app.post('/api/tutor/disputes/:id/appeal', verifyToken, requireTutor, async (req, res) => {
  const tutorId = req.user.userId;
  const { reason } = req.body;
  if (!reason || !reason.trim()) {
    return res.status(400).json({ message: 'Vui lòng nhập lý do kháng cáo.' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const disputeRes = await client.query('SELECT * FROM disputes WHERE id = $1 AND tutor_id = $2 FOR UPDATE', [req.params.id, tutorId]);
    if (!disputeRes.rows.length) {
      await client.query('ROLLBACK');
      return res.status(404).json({ message: 'Không tìm thấy khiếu nại.' });
    }
    const dispute = disputeRes.rows[0];

    // Must be resolved
    if (!dispute.status.startsWith('RESOLVED_')) {
      await client.query('ROLLBACK');
      return res.status(400).json({ message: 'Khiếu nại chưa được xử lý, không thể kháng cáo.' });
    }

    // Must not be appealed yet
    if (dispute.tutor_appeal_status) {
      await client.query('ROLLBACK');
      return res.status(400).json({ message: 'Bạn đã gửi kháng cáo cho khiếu nại này.' });
    }

    // Must be within 7 days
    const resolvedAt = new Date(dispute.resolved_at);
    const now = new Date();
    const diffDays = (now - resolvedAt) / (1000 * 60 * 60 * 24);
    if (diffDays > 7) {
      await client.query('ROLLBACK');
      return res.status(400).json({ message: 'Đã quá thời hạn 7 ngày để kháng cáo.' });
    }

    const updated = await client.query(
      `UPDATE disputes 
       SET tutor_appeal_status = 'PENDING', 
           tutor_appeal_reason = $1, 
           tutor_appealed_at = NOW() 
       WHERE id = $2 RETURNING *`,
      [reason.trim(), req.params.id]
    );

    // Notify Admin (get admin users)
    const adminRes = await client.query(`SELECT id FROM users WHERE role = 'admin'`);
    for (let admin of adminRes.rows) {
      await client.query(
        `INSERT INTO notifications (user_id, type, title, body, icon, ref_id, ref_type)
         VALUES ($1, 'system', 'Kháng cáo mới', 'Gia sư vừa gửi kháng cáo cho một khiếu nại.', 'report', $2, 'dispute')`,
        [admin.id, req.params.id]
      );
    }

    await client.query('COMMIT');
    res.json({ success: true, dispute: updated.rows[0] });
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error submitting appeal:', error);
    res.status(500).json({ error: 'Lỗi máy chủ' });
  } finally {
    client.release();
  }
});

app.get('/api/admin/dispute-appeals', verifyToken, requireAdmin, async (req, res) => {
  const client = await pool.connect();
  try {
    const query = `
      SELECT d.*, 
             u.full_name as student_name, 
             t.full_name as tutor_name,
             c.title as course_title
      FROM disputes d
      LEFT JOIN users u ON d.raised_by = u.id
      LEFT JOIN users t ON d.tutor_id = t.id
      LEFT JOIN courses c ON d.course_id = c.id
      WHERE d.tutor_appeal_status IS NOT NULL
      ORDER BY d.tutor_appealed_at DESC
    `;
    const result = await client.query(query);
    res.json(result.rows);
  } catch (error) {
    console.error('Error fetching admin appeals:', error);
    res.status(500).json({ error: 'Lỗi máy chủ' });
  } finally {
    client.release();
  }
});

app.post('/api/admin/dispute-appeals/:id/resolve', verifyToken, requireAdmin, async (req, res) => {
  const { status, response } = req.body;
  if (!['APPROVED', 'REJECTED'].includes(status)) {
    return res.status(400).json({ message: 'Trạng thái không hợp lệ.' });
  }
  if (!response || !response.trim()) {
    return res.status(400).json({ message: 'Vui lòng nhập phản hồi.' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const disputeRes = await client.query('SELECT * FROM disputes WHERE id = $1 FOR UPDATE', [req.params.id]);
    if (!disputeRes.rows.length) {
      await client.query('ROLLBACK');
      return res.status(404).json({ message: 'Không tìm thấy khiếu nại.' });
    }
    const dispute = disputeRes.rows[0];

    if (dispute.tutor_appeal_status !== 'PENDING') {
      await client.query('ROLLBACK');
      return res.status(400).json({ message: 'Kháng cáo này đã được xử lý.' });
    }

    let updatedReputation = null;

    if (status === 'APPROVED') {
      const repToRestore = dispute.reputation_points_deducted || 0;
      if (repToRestore > 0) {
        const tp = await client.query(
          `UPDATE tutor_profiles 
           SET reputation_score = reputation_score + $1 
           WHERE user_id = $2 RETURNING reputation_score`, 
          [repToRestore, dispute.tutor_id]
        );
        updatedReputation = tp.rows[0].reputation_score;
      }
    }

    const updated = await client.query(
      `UPDATE disputes 
       SET tutor_appeal_status = $1, 
           tutor_appeal_response = $2, 
           tutor_appeal_reviewed_at = NOW(),
           tutor_appeal_reviewed_by = $3
       WHERE id = $4 RETURNING *`,
      [status, response.trim(), req.user.userId, req.params.id]
    );

    // Notify Tutor
    const title = status === 'APPROVED' ? 'Kháng cáo được chấp nhận' : 'Kháng cáo bị từ chối';
    const body = status === 'APPROVED' 
      ? `Điểm uy tín đã được hoàn lại. Phản hồi: ${response.trim()}`
      : `Phản hồi: ${response.trim()}`;
    
    await client.query(
      `INSERT INTO notifications (user_id, type, title, body, icon, ref_id, ref_type)
       VALUES ($1, 'system', $2, $3, $4, $5, 'dispute')`,
      [dispute.tutor_id, title, body, status === 'APPROVED' ? 'check_circle' : 'cancel', req.params.id]
    );

    await client.query('COMMIT');
    res.json({ success: true, dispute: updated.rows[0], updatedReputation });
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Error resolving appeal:', error);
    res.status(500).json({ error: 'Lỗi máy chủ' });
  } finally {
    client.release();
  }
});
